<script setup>
import MEmptyState from '../../../components/mds/MEmptyState.vue';
defineProps({ title: String, description: String, columns: { type: Array, default: () => [] }, rows: { type: Array, default: () => [] }, loading: Boolean });
function value(row, column) { const raw = row?.[column.key]; if (column.money) return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(Number(raw || 0)); return raw === '' || raw == null ? '—' : raw; }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="border-b border-[var(--mds-border-light)] px-5 py-4"><h2 class="text-[16px] font-semibold">{{ title }}</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ description }}</p></header><MEmptyState v-if="!loading && !rows.length" title="Chưa có dữ liệu trong kỳ" description="Thử đổi kỳ báo cáo hoặc kiểm tra lại quyền truy cập."/><div v-else class="overflow-x-auto"><table class="min-w-full text-left text-[13px]"><thead class="bg-[var(--mds-neutral-200)] text-[var(--mds-text-secondary)]"><tr><th v-for="column in columns" :key="column.key" class="whitespace-nowrap border-b border-[var(--mds-border-light)] px-4 py-3 text-left font-semibold">{{ column.label }}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id || row.name || index" class="border-b border-[var(--mds-border-light)] hover:bg-[var(--mds-brand-50)]"><td v-for="column in columns" :key="column.key" :class="['px-4 py-3 align-top',column.money?'text-right font-medium tabular-nums':'']">{{ value(row,column) }}</td></tr></tbody></table></div></div></section></template>
